TLM.f("Sancti/07-28",{"officium":"Ss. Nazarii et Celsi Martyrum, Victoris I Papæ et Martyris ac Innocentii I Papæ et Confessoris","rule":["vide C3;","Gloria"],"fallback":"Commune/C3","from":{"Introitus":"Commune/C3","Tractus":"Commune/C3","Evangelium":"Commune/C3"},"sections":{"Introitus":[{"k":"ref","la":"Ps 78:11-12; 78:10"},{"k":"text","la":"Intret in conspéctu tuo, Dómine, gémitus compeditórum: redde vicínis nostris séptuplum in sinu eórum: víndica sánguinem Sanctórum tuórum, qui effúsus est."},{"k":"ref","la":"Ps 78:1"},{"k":"text","la":"Deus, venérunt gentes in hereditátem tuam: polluérunt templum sanctum tuum: posuérunt Jerúsalem in pomórum custódiam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Intret in conspéctu tuo, Dómine, gémitus compeditórum: redde vicínis nostris séptuplum in sinu eórum: víndica sánguinem Sanctórum tuórum, qui effúsus est."}],"Oratio":[{"k":"text","la":"Sanctórum tuórum nos, Dómine, Nazárii, Celsi, Victóris et Innocéntii conféssio beáta commúniat: et fragilitáti nostræ subsídium dignánter exóret."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Sap 10:17-20"},{"k":"text","la":"Réddidit Deus justis mercédem labórum suorum, et deduxit illos in via mirábili: et fuit illis in velaménto diei et in luce stellárum per noctem: tránstulit illos per Mare Rubrum, et transvéxit illos per aquam nímiam. Inimícos autem illórum demérsit in mare, et ab altitúdine inferórum edúxit illos. Ideo justi tulérunt spolia impiórum, et decantavérunt, Dómine, nomen sanctum tuum, et victrícem manum tuam laudavérunt páriter, Dómine, Deus noster."}],"Graduale":[{"k":"ref","la":"Exodi 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exodi 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Sir 44:14"},{"k":"text","la":"Córpora Sanctórum in pace sepúlta sunt, et nómina eórum vivent in generatiónem et generatiónem. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 21:9-19"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Cum audiéritis prǽlia et seditiónes, nolíte terréri: opórtet primum hæc fíeri, sed nondum statim finis. Tunc dicébat illis: Surget gens contra gentem, et regnum advérsus regnum. Et terræmótus magni erunt per loca, et pestiléntiæ, et fames, terrorésque de coelo, et signa magna erunt. Sed ante hæc ómnia injícient vobis manus suas, et persequéntur tradéntes in synagógas et custódias, trahéntes ad reges et praesides propter nomen meum: contínget autem vobis in testimónium. Pónite ergo in córdibus vestris non præmeditári, quemádmodum respondeátis. Ego enim dabo vobis os et sapiéntiam, cui non potérunt resístere et contradícere omnes adversárii vestri. Tradémini autem a paréntibus, et frátribus, et cognátis, et amícis, et morte affícient ex vobis: et éritis ódio ómnibus propter nomen meum: et capíllus de cápite vestro non períbit. In patiéntia vestra possidébitis ánimas vestras."}],"Offertorium":[{"k":"ref","la":"Ps 67:36"},{"k":"text","la":"Mirábilis Deus in Sanctis suis: Deus Israël, ipse dabit virtútem et fortitúdinem plebi suæ: benedíctus Deus, allelúja."}],"Secreta":[{"k":"text","la":"Concéde nobis, omnípotens Deus: ut his munéribus, quæ in sanctórum tuórum Nazarii, Celsi, Victóris et Innocéntii honóre deférimus, et te placémus exhíbitis, et nos vivificémur accéptis."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Sap 3:4-6"},{"k":"text","la":"Et si coram homínibus torménta passi sunt, Deus tentávit eos: tamquam aurum in fornáce probávit eos, et quasi holocáusta accépit eos."}],"Postcommunio":[{"k":"text","la":"Sanctórum Nazárii, Celsi, Victóris et Innocéntii, Dómine, intercessióne placátus: præsta, quǽsumus; ut, quod temporáli celebrámus actióne, perpétua salvatióne capiámus."},{"k":"macro","name":"Per Dominum"}]},"hr":{"fb339773d9c17ccf":{"t":"Ps 78, 11 i 12 i 10, Ps 78, 1\n(Ps 78, 11 i 12 i 10) Neka uzađu pred lice tvoje, Gospodine, uzdasi sužanjski, sedmerostruko vrati susjedima našim. Osveti prolivenu krv slugu svojih! (Ps 78, 1) Bože, narodi prodiru u nasljedstvo tvoje, skvrne sveti hram tvoj, pretvaraju Jeruzalem u razvaline.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 78, 11 i 12 i 10) Neka uzađu pred lice tvoje, Gospodine, uzdasi sužanjski, sedmerostruko vrati susjedima našim. Osveti prolivenu krv slugu svojih!","kn":"(Ps. 78. 11, 12, 10). Vapaj zarobljenih neka dođe pred lice Tvoje, Gospodine; vrati susjedima našim sedmerostruko u krilo njihovO'; osveti krv slugu svojih, koja je prolivena! (Ps. 78, 1) Bože! Provalili su bezbožnici u Tvoju baštinu, Jeruzalem su pretvorili u razvalinu! Slava Ocu. Vapaj.","knRef":"Kniewald 1942, str. 484–485 (snimka 243) (OCR)"},"adb9b540b4b68cf7":{"t":"<i>Pomolimo se</i>.\nBlaženo svjedočanstvo svetih tvojih Nazarija, Celza, Viktora i Inocenta neka nas, Gospodine, ojača i izmoli pomoć našoj slabosti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Ojačalo nas. Gospodine, blaženo mučeništvo Nazairija, Ce'lza i Viktora i zasluge blaženoga Inoicenta, te izmolilo pomoć našoj slabosti, po G, n.","knRef":"Kniewald 1942, str. 658–659 (snimka 330) (OCR)"},"96e6dd96580a83e6":{"t":"Mudr 10, 17-20\nČitanje knjige Mudrosti. Pravednicima je dao Bog nagradu za trude njihove. Vodio ih je čudesnim putem, bio im je zaklon po danu a zvjezdana svjetlost po noći. Vodio ih je preko Crvenoga mora i pratio preko velike vode. Njihove neprijatelje potopi u more. a njih izvede iz dubine morske. Tako su pravednici oplijenili bezbožnike, proslavili pjesmom sveto ime tvoje i jednodušno su hvalili pobjednicu ruku tvoju, Gospodine Bože naš.","kn":"Čitanje knjige Mudrosti (10, 17-20). Dade Bog platu /pravednicima za trud njihov, i povede ih čudesnim putem, i bijaše im zaklonište danju, a zvjezdana svjetlost noću; prevede ih preko Crvenoga mora, i izvede ih preko velike vode. Njihove nepirij atelje potopi u more, a njih izvede iz dubine groba. Zato pravednici primiše plijen bezbožnički, i zapjevaše. Gospodine, svetom imenu Tvojemu, i jednodušno proslaviše pobjednicu ruku Tvoju, Gospodine, Bože naš.","knRef":"Kniewald 1942, str. 658–659 (snimka 330) (OCR)"},"31f7cef74606cebe":{"t":"Izl 15, 11, Izl 15, 6\n(Izl 15, 11) Slavan je Bog u svojim svetima, divan u veličanstvu, čini čudesa. (Izl 15, 6) Snagom se proslavila desnica tvoja, Gospodine, desnica je tvoja uništila neprijatelje.\n\nSir 44, 14\n<i>Aleluja</i>, <i>aleluja</i>.\nTjelesa su svetih u miru sahranjena, a njihova imena žive od koljena do koljena. <i>Aleluja</i>.","kn":"(Izl. 15, 11). Slavan je Bog u svetima svojim, divan u veličanstvu, on čini čudesa. (Izl. 15, 6). Proslavila se desnica Tvoja, Gospodine, snagom svojom, desnica je Tvoja satrla neprijatelje!\n\nAleluja, aleluja! (Crkv. 44, 14) Tjelesa su svetih u miru sahranjena i imena njihova živu u vijeke vjekova.","knRef":"Kniewald 1942, str. 484–485 (snimka 243) (OCR)"},"ff852e407899a76c":{"t":"Lk 21, 9-19\nSlijedi sveto Evanđelje po Luki. U ono vrijeme reče Isus svojim učenicima: Kad čujete da se govori o ratovima i bunama, nemojte se plašiti, jer treba da to bude prije, ali još nije odmah svršetak. Tada im reče: Ustat će narod na narod i kraljevstvo na kraljevstvo i na različitim će mjestima biti veliki potresi i kuge i glad i strahote, a na nebu veliki znaci. Ali prije svega toga stavit će na vas ruke i progoniti, predavat će vas u sinagoge i bacati u tamnice, radi mene povlačit će vas pred kraljeve i upravitelje. I to će vam se dogoditi da vi posvjedočite. Zato budite mirni i ne smišljajte unaprijed kako ćete odgovarati, jer ću vam ja dati riječ i mudrost kojoj se neće moći oprijeti ni usprotiviti nitko od svih vaših protivnika. Bit ćete izdani od roditelja i braće i rođaka i prijatelja, a neke će od vas usmrtiti. Svi će vas mrziti radi mene, ali neće propasti ni vlas s vaše glave. Svojom strpljivošću spasit ćete svoj život.","kn":"t Slijedi sv. evanđelje po tuki (21, 9-19). U ono vrijeme reče Isus svojim učenicima: Kad čujete da se govori o ratovima i bunama, nemojte se plašiti, jer treba da to bude prije ali nema još odmah svršetka. Tada im reče: Ustat će narod na narod i kraljevstvo na kraljevstvo i na različitim će mjestima biti veliki potresi 1 kuge i glad i strahote, a na nebu veliki znaci. Ali prij e svega toga bacit će na vas ruke i progoniti, predavat će vas u sinagoge 1 bacati u tamnice, radi mene povlačit će vas pred kraljeve i upravitelje; 1 to će vam se dogoditi, da vi posvjedočite. Zato budite mirni, i ne smišljajte unaprijed, kako ćete odgovarati, jer ću vam ja dati riječi i mudrost, kojoj se ne će moći oprijeti ni usprotiviti nitko od svih vaših protivnika. Bit ćete izdani od roditelja i braće i rođaka i prijatelja, a neke će od vas usmrtiti. Svi će vas mrziti, radi mene, ali ne će propasti ni vlas s vaše glave. Svojom strpljivošću spasit ćete svoj život.","knRef":"Kniewald 1942, str. 798–799 (snimka 400) (OCR)"},"dd478a333f4e9a0c":{"t":"Ps 67, 36\nDivan je Bog u svojim svetima. Bog Izraelov daje krepost i snagu puku svojemu. Blagoslovljen Bog. <i>Aleluja</i>.","kn":"(Ps. 67, 36). Divan si. Gospodine, u svetištu svojem! Bog Izraelov daje krepost i snagu puku svojemu, blagoslovljen bio Bog!","knRef":"Kniewald 1942, str. 598–599 (snimka 300) (OCR)"},"41b3543ec5784c71":{"t":"Svemogući Bože, daj da po ovim darovima koje prinosimo na čast tvojih svetaca Nazarija, Celza, Viktora i Inocenta tebe umilostivimo a mi oživimo kad ih primimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Dopusti, svemogući Bože, da ' nas oživi prinos ovih darova o svetkovini svetih Tvojih Nazarija, Celsa, Viktora i Inocenta, a Tebe da ublaži, po G. n.","knRef":"Kniewald 1942, str. 658–659 (snimka 330) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"818b40676ad77c2d":{"t":"Mudr 3, 4 i 5 i 6\nI ako su pred ljudima trpjeli muke, Bog ih je iskušao. Prokušao ih je kao zlato u peći i primio ih je kao žrtve paljenice.","kn":"(Mudr. 3, 4-6). I ako su muke trpjeli pred ljudima. Bog, Ih je kušao; iskušao ih je kao zlato u peći i primio ih kao žrtvu paljenicu.","knRef":"Kniewald 1942, str. 798–799 (snimka 400) (OCR)"},"24a4b9017da02e9d":{"t":"<i>Pomolimo se</i>.\nGospodine, umilostivljen zagovorom svetog Nazarija, Celza, Viktora i Inocenta daj nam, molimo, da zaslužimo spasenje u vječnost ovim djelom što ga izvršavamo u vremenu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Umilostivljen zagovorom Tvojih svetih Nazarija, Celsa, Viktora i Inocenta, podaj nam, Gospodine, da vječnim .gašenjem primimo Oino, što vršimo vremenitom službom, po G. :n.","knRef":"Kniewald 1942, str. 658–659 (snimka 330) (OCR)"}},"variants":{"paschal":{"Introitus":[{"k":"ref","la":"Ps 63:3"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."},{"k":"ref","la":"Ps. 63:2"},{"k":"text","la":"Exáudi, Deus, oratiónem meam cum déprecor: a timóre inimíci éripe ánimam meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Joánnem"},{"k":"ref","la":"Joannes 15:1-7"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Ego sum vitis vera: et Pater meus agrícola est. Omnem pálmitem in me non feréntem fructum, tollet eum: et omnem, qui fert fructum, purgábit eum, ut fructum plus áfferat. Jam vos mundi estis propter sermónem, quem locútus sum vobis. Manéte in me: et ego in vobis. Sicut palmes non potest ferre fructum a semetípso, nisi mánserit in vite: sic nec vos, nisi in me manséritis. Ego sum vitis, vos pálmites: qui manet in me, et ego in eo, hic fert fructum multum: quia sine me nihil potéstis fácere. Si quis in me non mánserit, mittétur foras sicut palmes, et aréscet, et cólligent eum, et in ignem mittent, et ardet. Si manséritis in me, et verba mea in vobis mánserint: quodcúmque voluéritis, petétis, et fiet vobis."}]}}});
